@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Cabinet+Grotesk:wght@500;700;800&display=swap');

:root {
  --bg: #ffffff;
  --bg-soft: #f7f6ff;
  --bg-tint: #f2f0ff;
  --text: #101225;
  --muted: #59607a;
  --primary: #5b3df5;
  --primary-2: #7d66ff;
  --primary-3: #ede9ff;
  --accent: #17c8ff;
  --success: #11b981;
  --border: #e6e8f4;
  --shadow: 0 14px 40px rgba(52, 39, 133, 0.12);
  --radius: 18px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: radial-gradient(circle at 85% 0%, #efebff 0%, #fff 42%);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
.container { width: min(1160px, 92vw); margin: 0 auto; }
.nav-wrap {
  position: sticky; top: 0; z-index: 100;
  backdrop-filter: blur(10px);
  background: rgba(255,255,255,.88);
  border-bottom: 1px solid var(--border);
}
.nav {
  height: 76px; display: flex; align-items: center; justify-content: space-between;
}
.brand { display: flex; align-items: center; gap: .7rem; font-weight: 800; font-size: 1.1rem; }
.brand-badge {
  width: 34px; height: 34px; border-radius: 10px;
  background: linear-gradient(140deg, var(--primary), var(--accent));
  box-shadow: 0 6px 16px rgba(91,61,245,.35);
}
.nav-links { display: flex; align-items: center; gap: 1rem; color: var(--muted); font-weight: 600; }
.nav-links a { padding: .5rem .8rem; border-radius: 10px; }
.nav-links a:hover { color: var(--primary); background: var(--primary-3); }
.nav-cta { display: flex; align-items: center; gap: .7rem; }
.btn {
  border: 0; border-radius: 12px; padding: .78rem 1.1rem; font-weight: 700; cursor: pointer;
  transition: .25s transform, .25s box-shadow, .25s background;
}
.btn:hover { transform: translateY(-2px); }
.btn-primary {
  background: linear-gradient(135deg, var(--primary), var(--primary-2)); color: #fff;
  box-shadow: 0 10px 22px rgba(91,61,245,.33);
}
.btn-primary:hover { box-shadow: 0 14px 28px rgba(91,61,245,.42); }
.btn-ghost { background: #fff; border: 1px solid var(--border); color: var(--text); }
.badge { display: inline-block; border-radius: 999px; font-size: .78rem; font-weight: 700; padding: .3rem .7rem; }
.badge-soft { background: var(--primary-3); color: var(--primary); }
.badge-success { background: #e9fbf4; color: #098f64; }
section { padding: 84px 0; }
.section-soft { background: var(--bg-soft); }
.section-tint { background: var(--bg-tint); }
.eyebrow { color: var(--primary); font-weight: 800; letter-spacing: .04em; text-transform: uppercase; font-size: .78rem; }
.h1, h1 { font-family: 'Cabinet Grotesk', 'Plus Jakarta Sans', sans-serif; font-size: clamp(2rem, 4.5vw, 4rem); line-height: 1.05; margin: .6rem 0 1rem; }
h2 { font-family: 'Cabinet Grotesk', 'Plus Jakarta Sans', sans-serif; font-size: clamp(1.7rem, 3vw, 2.7rem); margin: .6rem 0 1rem; line-height: 1.1; }
h3 { margin: .5rem 0; font-size: 1.1rem; }
.lead { color: var(--muted); font-size: 1.08rem; max-width: 700px; }
.grid { display: grid; gap: 1.1rem; }
.hero-grid { grid-template-columns: 1.15fr .85fr; align-items: center; gap: 2rem; }
.card {
  background: #fff; border: 1px solid var(--border); border-radius: var(--radius);
  padding: 1.15rem; box-shadow: var(--shadow);
}
.mockup {
  border-radius: 20px; border: 1px solid #dddffc; background: linear-gradient(180deg,#fff,#f8f8ff);
  padding: 1rem; box-shadow: 0 20px 40px rgba(91,61,245,.15);
}
.mockup-bar { height: 12px; width: 60%; border-radius: 999px; background: linear-gradient(90deg,var(--primary), var(--accent)); margin-bottom: .7rem; }
.mockup-line { height: 10px; border-radius: 999px; background: #e8eaf9; margin-bottom: .6rem; }
.cols-2 { grid-template-columns: repeat(2,minmax(0,1fr)); }
.cols-3 { grid-template-columns: repeat(3,minmax(0,1fr)); }
.cols-4 { grid-template-columns: repeat(4,minmax(0,1fr)); }
.kpi { font-size: clamp(1.8rem, 3vw, 2.8rem); font-weight: 800; color: var(--primary); margin-bottom: .35rem; }
.list { margin: .6rem 0 0; padding-left: 1.1rem; color: var(--muted); }
.list li { margin: .35rem 0; }
.logo-row { display: grid; grid-template-columns: repeat(6,minmax(0,1fr)); gap: .8rem; }
.logo { border: 1px dashed #d9dcf8; border-radius: 12px; padding: .8rem; text-align: center; color: var(--muted); font-weight: 700; background: #fff; }
.cta-band {
  border-radius: 28px; background: linear-gradient(135deg,#5b3df5,#7f63ff,#2bb8ff);
  padding: 2.4rem; color: #fff; box-shadow: 0 26px 46px rgba(69,53,180,.3);
}
.footer { padding: 44px 0; border-top: 1px solid var(--border); color: var(--muted); }
.small { font-size: .9rem; color: var(--muted); }
.form { max-width: 430px; margin: 1rem auto 0; }
.input {
  width: 100%; border: 1px solid var(--border); background: #fff; border-radius: 12px;
  padding: .85rem .9rem; font: inherit;
}
.auth-page { min-height: calc(100vh - 76px); display: grid; place-items: center; padding: 2rem 0; }
.auth-card { width: min(980px, 94vw); display: grid; grid-template-columns: 1fr 1fr; gap: 1.2rem; }
.socials { display: grid; gap: .7rem; margin-top: .8rem; }
.social-btn { width: 100%; text-align: left; background: #fff; border: 1px solid var(--border); border-radius: 12px; padding: .75rem .9rem; font-weight: 600; }
.pricing-controls { display: flex; gap: 1rem; align-items: center; flex-wrap: wrap; margin-bottom: 1rem; }
.toggle { background: #fff; border: 1px solid var(--border); border-radius: 999px; padding: .25rem; display: inline-flex; }
.toggle button { border: 0; background: transparent; padding: .45rem .85rem; border-radius: 999px; font-weight: 700; cursor: pointer; }
.toggle button.active { background: var(--primary); color: #fff; }
.slider-wrap { max-width: 420px; }
.plan-price { font-size: 2rem; font-weight: 800; color: var(--text); }
.plan-meta { color: var(--muted); font-size: .9rem; }
.plan-actions { display: flex; gap: .6rem; margin-top: .9rem; }
.feature-list { max-height: 0; overflow: hidden; transition: max-height .3s ease; }
.feature-list.open { max-height: 280px; margin-top: .7rem; }
.table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid var(--border); border-radius: 16px; overflow: hidden; }
.table th, .table td { padding: .8rem; border-bottom: 1px solid var(--border); text-align: left; font-size: .92rem; }
.table th { background: #f7f8ff; }
.accordion-item { border: 1px solid var(--border); border-radius: 14px; background: #fff; margin-bottom: .7rem; overflow: hidden; }
.acc-btn { width: 100%; border: 0; background: #fff; text-align: left; padding: .9rem 1rem; font-weight: 700; cursor: pointer; }
.acc-content { max-height: 0; overflow: hidden; transition: .3s ease; padding: 0 1rem; color: var(--muted); }
.acc-content.open { max-height: 160px; padding-bottom: .9rem; }
.cookie-banner {
  position: fixed; left: 50%; bottom: 18px; transform: translateX(-50%); width: min(900px, 94vw);
  background: #fff; border: 1px solid var(--border); border-radius: 16px; box-shadow: var(--shadow); z-index: 120;
  display: none; padding: 1rem;
}
.cookie-banner.show { display: block; }
.cookie-modal {
  position: fixed; inset: 0; background: rgba(15,17,36,.5); display: none; place-items: center; z-index: 130;
}
.cookie-modal.show { display: grid; }
.cookie-modal .panel { width: min(560px, 94vw); }
.toggle-row { display: flex; align-items: center; justify-content: space-between; margin: .7rem 0; }
.switch { width: 46px; height: 26px; border-radius: 999px; border: 1px solid var(--border); background: #eceffd; position: relative; cursor: pointer; }
.switch::after { content: ''; width: 20px; height: 20px; border-radius: 999px; background: #fff; position: absolute; top: 2px; left: 2px; transition: .2s; box-shadow: 0 2px 4px rgba(0,0,0,.18); }
.switch.on { background: var(--primary); }
.switch.on::after { left: 22px; }
@media (max-width: 920px) {
  .hero-grid, .auth-card, .cols-4, .cols-3, .cols-2 { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  section { padding: 62px 0; }
  .logo-row { grid-template-columns: repeat(3,minmax(0,1fr)); }
}
